pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable DEFAULT_ADMIN = address(this);

    function setUp() public {
        // Deploy with minDelay 0, a single proposer and a single executor (both this contract)
        address[] memory proposers = new address[](1);
        proposers[0] = DEFAULT_ADMIN;
        address[] memory executors = new address[](1);
        executors[0] = DEFAULT_ADMIN;
        c = new C(0, proposers, executors);
    }

    function testFuzz_property(address account, bytes32 role) public {
        // Ensure we do not use the zero address as account for granting, but we can still test it.
        // We need a role that was actually granted to account.
        // Grant the fuzzed role to account using the DEFAULT_ADMIN_ROLE admin relationship.
        // First make this contract the admin of the fuzzed role.
        // Since DEFAULT_ADMIN_ROLE (0x00) is admin of itself by default, we can grant any role via grantRole.
        vm.startPrank(DEFAULT_ADMIN);
        // Set the admin of the fuzzed role to DEFAULT_ADMIN_ROLE so we can grant it.
        // DEFAULT_ADMIN_ROLE is bytes32(0), which hasRole for this contract because _setupRole was called for it.
        c.grantRole(role, account);
        vm.stopPrank();

        // Read the actual hasRole result
        bool actualHasRole = c.hasRole(role, account);

        // The rule: after granting a role to an account, hasRole must return true.
        // The buggy version returns false, so the assertion fails for any non-reverting grant.
        assertTrue(actualHasRole);
    }
}

