pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address caller, address target, bytes32 role) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));
        vm.assume(caller != target);
        vm.assume(!c.hasRole(role, caller));
        vm.assume(!c.hasRole(role, target));

        // Grant the role to the target account
        bytes32 adminRole = c.getRoleAdmin(role);
        vm.assume(adminRole != bytes32(0));
        vm.assume(c.hasRole(adminRole, address(this)));
        c.grantRole(role, target);

        vm.assume(c.hasRole(role, target));

        // Caller tries to renounce target's role
        vm.prank(caller);
        try c.renounceRole(role, target) {
            // Buggy contract allows renouncing for others, so target loses role
            bool targetHasRoleAfter = c.hasRole(role, target);
            assertTrue(!targetHasRoleAfter);
        } catch {
            // Correct contract reverts, so target should still have the role
            bool targetHasRoleAfter = c.hasRole(role, target);
            assertTrue(targetHasRoleAfter);
        }
    }
}

