pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        address[] memory proposers = new address[](1);
        proposers[0] = address(this);
        address[] memory executors = new address[](1);
        executors[0] = address(this);
        c = new C(0, proposers, executors);
    }

    function testFuzz_property(address account) public {
        // account must be a PROPOSER holder so renounceRole is callable
        bytes32 role = c.PROPOSER_ROLE();
        vm.assume(account != address(0));
        vm.assume(!c.hasRole(role, account));
        vm.prank(address(this));
        c.grantRole(role, account);

        // account calls renounceRole for itself
        vm.prank(account);
        bool ok;
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }

        // reference allows self-renouncement; buggy version prevents it (reverts)
        assertTrue(ok);
    }
}

